INSERT INTO public.blocks (project_id, type, content, order_index)
VALUES ((SELECT id FROM public.projects WHERE slug = 'immersive-traffic-command'), 'FeaturesGrid', '{"heading":"The Quantum of the Problem","columns":3,"items":[{"title":"Economic Hemorrhage","description":"India loses ~3% of GDP annually to inefficiency. Static signals create bottlenecks."},{"title":"\"Golden Hour\" Failure","description":"1.5 Lakh+ annual deaths. Officers \"freeze\" when ambulances approach."},{"title":"The Safety Deficit","description":"Rising aggression & public distrust. Minor stops turn into major conflicts."}]}'::jsonb, 2);

