INSERT INTO public.blocks (project_id, type, content, order_index)
VALUES ((SELECT id FROM public.projects WHERE slug = 'immersive-traffic-command'), 'CombinedResearch', '{"heading":"Primary Research Insights","interviews":{"heading":"Problem Areas","findings":[{"id":1,"title":"Gap Between Theory and Practice","description":"Classroom learning doesn''t prepare for chaotic real-time road decisions."},{"id":2,"title":"High Learning Curve","description":"New recruits face a confidence gap."},{"id":3,"title":"Resource Constraints","description":"Lack of fixed structure; reliance on inconsistent on-the-job learning."}]},"surveys":{"heading":"Opportunity Areas","findings":[{"id":1,"title":"Virtual Simulation","description":"Risk-free practice for high-stress scenarios."},{"id":2,"title":"Adaptive Learning","description":"Digital simulations tracking response to traffic flow."},{"id":3,"title":"AI Integration","description":"Data-based management and investigation procedures."}]},"image":"/assets/projects/immersive-traffic-command/page_12.png"}'::jsonb, 9);

