INSERT INTO public.blocks (project_id, type, content, order_index)
VALUES ((SELECT id FROM public.projects WHERE slug = 'immersive-traffic-command'), 'SpatialUIDesign', '{"navLabel":"Spatial UI","hero":{"eyebrow":"SPATIAL UI + INFORMATION ARCHITECTURE","headline":"Designing information around attention","subheading":"In VR, the interface exists inside the user''s environment. I designed the information architecture around the trainee''s field of view, separating task-critical information from system controls and progressively reducing guidance as confidence increased."},"block1":{"heading":"Designing for the user''s natural field of view","copy":"VR changes the relationship between the user and the interface. Information cannot simply be placed on a fixed screen—it has to exist within the user''s physical environment without interrupting the primary task.","image":"/assets/projects/immersive-traffic-command/page_18.png","cards":[{"title":"01 — FIELD OF VIEW","desc":"Tutorial information stays within the central viewing area to reduce unnecessary head movement."},{"title":"02 — SPATIAL LEGIBILITY","desc":"UI elements are scaled according to viewing distance so instructions remain readable without becoming intrusive."},{"title":"03 — DEPTH","desc":"Controlled virtual distances help maintain comfortable visual focus during interaction."}],"metadata":"110° FOV · Spatial scaling · Controlled depth"},"block2":{"image":"/assets/projects/immersive-traffic-command/page_19.png","pullQuote":"The interface was designed to support the task—not compete with it.","labels":["CENTRAL VIEW","OPERATIONAL INFORMATION","WORLD / TASK AREA"]},"block3":{"eyebrow":"INFORMATION ARCHITECTURE","heading":"Two layers of information. Two different user states.","copy":"Not every piece of information deserves the user''s attention at the same time. I separated the interface into two layers based on what the trainee is trying to do.","perfTitle":"01 — PERFORMANCE LAYER","perfDesc":"Operational information remains available while the trainee manages traffic.","perfTags":["Status","Score","Time","Errors"],"sysTitle":"02 — SYSTEM LAYER","sysDesc":"Simulation controls appear separately so actions such as pause, restart and mode selection do not compete with traffic management.","sysTags":["Resume","Restart","Training","Quit"],"imgOp":"/assets/projects/immersive-traffic-command/page_22.png","imgSys":"/assets/projects/immersive-traffic-command/page_23.png"},"block4":{"caption":"The hierarchy is based on attention, not just content."},"block5":{"headline":"Teach the gesture. Then take the hint away.","text":"The training experience progressively removes assistance. Users first learn the physical gesture, then practise it with feedback, and finally perform it against live traffic without visual prompts.","steps":[{"id":"01","title":"LEARN","text":"Ghost Hand demonstrates the required gesture."},{"id":"02","title":"PRACTISE","text":"The trainee reproduces the gesture through hand tracking."},{"id":"03","title":"VERIFY","text":"Visual and audio feedback confirms whether the gesture was recognised."},{"id":"04","title":"EVALUATE","text":"Visual guidance disappears and the trainee responds independently."}]},"block6":{"imgTut":"/assets/projects/immersive-traffic-command/page_24.png","imgEval":"/assets/projects/immersive-traffic-command/page_25.png","tutTitle":"TUTORIAL MODE","tutDesc":"Build confidence before complexity.","tutList":["Guided","Ghost Hand demonstrations","One gesture at a time","Immediate feedback"],"evalTitle":"EVALUATION MODE","evalDesc":"Remove the support. Keep the pressure.","evalList":["Independent","No visual gesture hints","Live traffic","Recall-based decisions"]},"block7":{"heading":"A progressive learning loop","cards":[{"title":"GUIDED","desc":"Ghost Hand demonstrations support first-time learning."},{"title":"PROGRESSIVE","desc":"Tasks increase in complexity rather than presenting everything at once."},{"title":"SELF-PACED","desc":"Next / Back navigation allows users to control their learning pace."},{"title":"REWARDED","desc":"Immediate visual and audio feedback reinforces correct actions."}]},"block8":{"statement":"The interface supports the decision. It doesn''t become the decision.","text":"Every UI element was evaluated against one question: does this help the trainee manage traffic, or does it pull their attention away from it?","footerLines":[{"label":"WHERE","value":"Visual ergonomics"},{"label":"WHAT","value":"Information architecture"},{"label":"WHEN","value":"State-dependent UI"},{"label":"HOW","value":"Progressive guidance"}]}}'::jsonb, 17);

INSERT INTO public.blocks (project_id, type, content, order_index)
VALUES ((SELECT id FROM public.projects WHERE slug = 'immersive-traffic-command'), 'ExpandableCards', '{"heading":"Usability Heuristics (Nielsen & Shneiderman)","cards":[{"title":"Visibility of System Status","content":"Progress bar, HUD elements for score/time, synchronized hand cutouts."},{"title":"Match System & Real World","content":"MoRTH standards, Indian junction layouts, senior trainer character."},{"title":"Error Prevention","content":"Strike system (3 lives), collision physics, Ghost Hands visual scaffolding."},{"title":"Recognition vs Recall","content":"Visual hints, spatial audio cues."},{"title":"Offer Informative Feedback","content":"\"Ding\" sound + Tick icon for successful signals."}]}'::jsonb, 18);

INSERT INTO public.blocks (project_id, type, content, order_index)
VALUES ((SELECT id FROM public.projects WHERE slug = 'immersive-traffic-command'), 'Learnings', '{"heading":"Testing Feedback & Iterations","items":[{"problem":"Did you feel overwhelmed or \"frozen\" when the evaluation mode started?","learning":"Initial Freezing: Two people reported feeling overwhelmed due to forgetting actions when vehicles approached."},{"problem":"Is this VR practice better than reading the training manual?","learning":"Effectiveness: VR practice is universally considered superior because of actual engagement, real-scenario practice, and multi-sensory experiences."},{"problem":"Did the Invisible Detection Boxes accurately catch your hand gestures?","learning":"Accuracy Issues: Detection was sometimes inconsistent. Needed adjustments for height issues and box sizes."}]}'::jsonb, 19);

